#![forbid(unsafe_code)]

#[path = "../contracts.rs"]
mod contracts;

use contracts::{CaptureState, ProbeError, ProbeEvent, ProbeReply, ProbeRequest};
use ts_rs::TS;

fn main() {
    let config = ts_rs::Config::default();
    let definitions = [
        CaptureState::decl(&config),
        ProbeRequest::decl(&config),
        ProbeReply::decl(&config),
        ProbeError::decl(&config),
        ProbeEvent::decl(&config),
    ];
    let text = format!(
        "// Generated by ts-rs 12.0.1 from src-tauri/src/contracts.rs. Do not edit.\n{}\n",
        definitions
            .map(|definition| format!("export {definition}"))
            .join("\n\n")
    );
    print!("{text}");
}
